  sbua = NULL,
  plot_size = NULL,
  bedrooms = 3,
  hook_line = 'A fully furnished 3BHK villa with a private pool in one of Porvorim''s most prestigious gated communities.',
  summary = 'Fully furnished 3BHK villa in Pinto Rosario Square, Porvorim — a prestigious gated villa community with a private pool, two common pools, gym and 24/7 security.',
  description = 'Own a luxury 3BHK villa with a private pool in Pinto Rosario Square, one of the most prestigious gated villa communities in North Goa. Located in the heart of Porvorim, this fully furnished villa is a rare opportunity for homebuyers and investors seeking premium real estate in a prime location.

Built across 220 sqm, the villa is thoughtfully designed for modern luxury living and comes fully air-conditioned with premium white goods, elegant interiors, spacious living areas, and a dedicated maid''s quarters. One of the standout features of this property is its private swimming pool — a rare offering within the community.

The gated complex is known for its premium lifestyle amenities, including two common swimming pools, a fully equipped gym, landscaped open spaces, children''s play area, and excellent security, making it ideal for families, holiday homeowners, and luxury property investors.

Strategically located in Porvorim, North Goa, the villa offers seamless access to Panjim, Candolim, Calangute, top restaurants, beaches, schools, and entertainment hubs.',
  highlights = '220 sqm built area, private pool, fully furnished, air-conditioned, maid''s quarters, two common pools, gym, security',
  completion_date = NULL,
